    o=L(36,20,36,170)+L(36,170,340,170)
    for h,v in enumerate(LD):
        o+=R(X(h),Y(v),10,170-Y(v),'bxa' if h in NIGHT else 'soft',1)
    o+=f'<line x1="36" y1="{Y(25)}" x2="336" y2="{Y(25)}" class="ln dash"/>'+TL(120,Y(25)-4,'мақсат: 25 кВт','t-s mu')
    o+=TL(40,16,'қуат, кВт','t-s t-b')+TL(120,34,'түнгі базалық жүктеме 45 кВт','t-s ac')
    for h in (0,6,12,18):o+=T(X(h)+5,184,str(h),'t-s mu')
    o+=TL(250,198,'тәулік сағаты','t-s mu')
    return S(340,206,o,'Ғимараттың тәуліктік жүктеме графигі')
