    o+=L(X(0),Y(-25),X(10),Y(-25+sv/1e6*10),'lna')
    o+=f'<line x1="{X(pb)}" y1="{Y(0)}" x2="{X(pb)}" y2="150" class="ln dash"/>'+T(X(pb),164,f'{pb:.1f} жыл','t-s ac')
    o+=TL(44,Y(-25)+14,'−25 (инвестиция)','t-s mu')
    for t in (0,2,4,6,8,10):o+=T(X(t),114,str(t),'t-s mu')
    o+=TL(250,196,'жыл','t-s mu')
    return S(340,204,o,'Өтелу мерзімі')
